<template><view class="business-home"><jk-page-nav title="九州康业务中心"></jk-page-nav>
  <view class="identity-banner"><view class="avatar">{{ roleName.slice(0,1) }}</view><view class="identity-copy"><view><strong>{{ roleName }}</strong><text>{{ context.freezeStatus?'身份冻结':'身份正常' }}</text></view><view>{{ context.regionName||context.regionCode||'区域未配置' }}</view><view>有效期：长期有效</view></view><button @click="goStatus">身份详情 ›</button></view>
  <view class="card overview"><view class="section-head"><strong>业务数据概览</strong><text>数据说明 ›</text></view><view class="metrics"><view><text>库存价值(元)</text><strong>{{ stockValue }}</strong></view><view><text>累计收益(元)</text><strong>{{ incomeValue }}</strong></view><view><text>待处理事项</text><strong>{{ pendingCount }}</strong></view></view></view>
  <view class="card"><view class="section-head"><strong>常用功能</strong></view><view class="menu-grid"><view v-for="item in menus" :key="item.name" @click="go(item.url)"><text>{{ item.icon }}</text><strong>{{ item.name }}</strong></view></view></view>
  <view class="card"><view class="section-head"><strong>待处理事项</strong><text @click="go('/pages/jk/trade/list?mode=order')">全部 ›</text></view><view class="pending"><text>平台订单待处理</text><strong>{{ pendingCount }} ›</strong></view></view>
</view></template>
<script>import JkPageNav from '@/components/jk/jk-page-nav.vue';import {getJkPermissionContext,getJkMyStock,getJkCommissionSummary,getJkPlatformOrderList} from '@/api/jk.js';const ROLE={maker:'创客',partner:'合伙人',county_agent:'区县代',normal_user:'普通用户'};export default{components:{JkPageNav},data(){return{context:{},stockValue:'--',incomeValue:'--',pendingCount:0};},computed:{roleName(){return this.context.primaryRoleName||ROLE[this.context.primaryRoleCode]||'普通用户';},menus(){return[{name:'平台订货',icon:'▣',url:'/pages/jk/trade/list?mode=order'},{name:'我的库存',icon:'▤',url:'/pages/jk/stock/index'},{name:'库存流水',icon:'▥',url:'/pages/jk/stock/flow'},{name:'收益中心',icon:'¥',url:'/pages/jk/commission/index'},{name:'资金账户',icon:'▣',url:'/pages/jk/fund/account'},{name:'提现申请',icon:'￥',url:'/pages/jk/withdraw/apply'}];}},onShow(){this.load();},methods:{load(){getJkPermissionContext().then(r=>{this.context=r.data||r||{}});getJkMyStock().then(r=>{let d=r.data||r||{};this.stockValue=this.money(d.totalValue||d.stockValue||d.totalAmount)}).catch(()=>{});getJkCommissionSummary().then(r=>{let d=r.data||r||{};this.incomeValue=this.money(d.totalCommissionAmount||d.totalAmount||d.settledAmount)}).catch(()=>{});getJkPlatformOrderList({page:1,limit:50}).then(r=>{let d=r.data||r||{};let rows=d.list||d.records||[];this.pendingCount=rows.filter(x=>['CREATED','PAYMENT_SUBMITTED','SHIPPED'].indexOf(x.status)>=0).length}).catch(()=>{});},money(v){return v===undefined||v===null?'--':Number(v).toFixed(2);},go(u){uni.navigateTo({url:u});},goStatus(){uni.navigateTo({url:'/pages/jk/identity/status'});}}};</script>
<style lang="scss">.business-home{min-height:100vh;padding:0 24rpx 60rpx;background:#f8fbfa}.identity-banner{display:flex;align-items:center;margin:26rpx 0;padding:34rpx 28rpx;border-radius:26rpx;background:linear-gradient(135deg,#08c4a0,#9ae9db);color:#fff}.avatar{display:flex;align-items:center;justify-content:center;width:100rpx;height:100rpx;margin-right:24rpx;border-radius:50%;background:#fff;color:#08b996;font-size:45rpx;font-weight:700}.identity-copy{flex:1;font-size:26rpx;line-height:1.7}.identity-copy strong{margin-right:14rpx;font-size:37rpx}.identity-copy text{padding:6rpx 13rpx;border-radius:10rpx;background:#0ab697;font-size:22rpx}.identity-banner button{border-radius:36rpx;background:#fff;color:#08ae8d;font-size:25rpx}.card{margin-bottom:24rpx;padding:28rpx;border-radius:24rpx;background:#fff;box-shadow:0 6rpx 22rpx rgba(20,70,58,.06)}.section-head{display:flex;justify-content:space-between;margin-bottom:26rpx}.section-head strong{font-size:34rpx}.section-head text{color:#7f8996;font-size:25rpx}.metrics{display:flex}.metrics view{display:flex;flex:1;flex-direction:column;gap:18rpx;border-right:1rpx solid #e7eceb;text-align:center}.metrics view:last-child{border:0}.metrics text{color:#7c8794;font-size:24rpx}.metrics strong{font-size:31rpx}.menu-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:34rpx 10rpx}.menu-grid view{display:flex;flex-direction:column;align-items:center;gap:12rpx}.menu-grid text{display:flex;align-items:center;justify-content:center;width:70rpx;height:70rpx;border-radius:18rpx;background:#def9f2;color:#08b996;font-size:36rpx}.menu-grid strong{font-size:25rpx;font-weight:500}.pending{display:flex;justify-content:space-between;color:#4a5562;font-size:28rpx}.pending strong{color:#08ae8d}</style>
